function calendarEntries(){const entries=[{id:'applied-stuck',date:'2026-10-06',type:'Applied',company:'STUCK'},{id:'applied-govtech',date:'2026-10-12',type:'Applied',company:'GovTech'},{id:'applied-tiktok',date:'2026-10-20',type:'Applied',company:'TikTok'},{id:'applied-sap',date:'2026-10-23',type:'Applied',company:'SAP'}];data.interviews.forEach(it=>entries.push({id:it.id,date:it.date,type:'Interview',company:it.company,title:it.title,time:it.time,location:it.location,round:it.round}));data.savedEvents.forEach(id=>{let e=eventData[id];if(e)entries.push({id:'event-'+id,eventId:id,date:'2026-'+(e[1]==='OCT'?'10':'11')+'-'+e[0],type:'Event',title:e[2],category:e[4],location:['Singapore','Online','Singapore','Online','Singapore','Singapore'][id]})});return entries}
function today(){let date=new Date(calendarMonth+'-01T12:00:00'),start=new Date(date),offset=(date.getDay()+6)%7;start.setDate(1-offset);let count=Math.ceil((offset+new Date(date.getFullYear(),date.getMonth()+1,0).getDate())/7)*7,entries=calendarEntries();return `<h1>Today</h1><div class="today"><section class="card"><div class="row between wrap"><h2>${date.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</h2><div class="row"><button class="calendar-nav" data-calendar-month="-1" aria-label="Previous month">‹</button><button class="calendar-nav" data-calendar-month="0">Today</button><button class="calendar-nav" data-calendar-month="1" aria-label="Next month">›</button></div></div><div class="row wrap" style="margin-bottom:18px"><span class="badge Applied">Applied</span><span class="badge Interview">Interview</span><span class="badge Event">Saved event</span><small>Demo · 26 Oct</small></div><div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="dayname">${d}</div>`).join('')}${Array.from({length:count},(_,i)=>{let d=new Date(start);d.setDate(start.getDate()+i);let key=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'),items=entries.filter(e=>e.date===key),isToday=key==='2026-10-26';return `<div class="day ${isToday?'todayday':''} ${d.getMonth()!==date.getMonth()?'outside-month':''}"><button class="day-number" data-calendar data-date="${key}" aria-label="${d.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}">${d.getDate()}${isToday?' · Today':''}</button>${items.map(e=>`<button class="event ${e.type}" data-calendar data-date="${key}" data-entry="${esc(e.id)}" aria-label="${esc(e.type+' · '+(e.title||e.company))}">${e.type==='Interview'?esc(e.time)+' ':''}${esc(e.title||e.company)}</button>`).join('')}</div>`}).join('')}</div><div class="footnote">Sample dates · SGT · Saved Job Events appear here automatically</div></section><aside class="stack"><div>${interviewContext()}</div><section class="card"><div class="row between"><h3>Actions</h3><small>To do</small></div>${task('resume-review','Resume review','Figma · Design resume v3','#profile')}${task('follow-up','Follow-up','Grab · UX Research Intern','#jobs')}${data.reading?task('reading-action','Use one idea from your reading','Your saved note','#profile'):''}</section><section class="card soft"><div class="row between"><span class="pill attention">AI ASSIST</span><small>≈ 2 min</small></div><h2 class="sectiongap">${activeInterview().outline?'Your outline is ready':'Interview prep outline'}</h2><div class="row wrap"><small>${activeInterview().stories.length} saved stories</small><small>Role requirements</small><small>Key questions</small></div><div class="row sectiongap"><button class="primary" data-action="${activeInterview().outline?'outline':'generate'}">${activeInterview().outline?'View outline':'Generate outline'}</button><a href="#interviews">Review materials →</a></div></section></aside></div>`}
function filtered(){return data.jobs.filter(j=>(!query||`${j.company} ${j.title}`.toLowerCase().includes(query.toLowerCase()))&&(!filters.Category.length||filters.Category.includes(j.category))&&(!filters.Location.length||filters.Location.includes(j.location))&&(!filters.Progress.length||filters.Progress.includes(j.status)))}
